// Phase 3 / Module 15, chapter C: trees, binary search trees, heaps and graphs.
"use strict";
const { chain, graph, table, svgWrap, esc } = require("./render");
const { mcq, task } = require("./lib");

const lessons = [];
const tx = (x, y, s, size = 13, anchor = "middle") => `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}" fill="currentColor" font-family="system-ui,sans-serif">${esc(s)}</text>`;

const TREE_SETUP = `from collections import deque\n\nclass TreeNode:\n    def __init__(self, val, left=None, right=None):\n        self.val, self.left, self.right = val, left, right\n\ndef build_tree(tokens):\n    if not tokens or tokens[0] == "null":\n        return None\n    root = TreeNode(int(tokens[0]))\n    queue, i = deque([root]), 1\n    while queue and i < len(tokens):\n        node = queue.popleft()\n        if i < len(tokens) and tokens[i] != "null":\n            node.left = TreeNode(int(tokens[i]))\n            queue.append(node.left)\n        i += 1\n        if i < len(tokens) and tokens[i] != "null":\n            node.right = TreeNode(int(tokens[i]))\n            queue.append(node.right)\n        i += 1\n    return root\n`;
const node = (id, t, x, y, k = "proc") => ({ id, k, t, x, y, w: 54, h: 40 });

// ---------------------------------------------------------------- 1
lessons.push({
  title: "Trees and Binary Trees: Terminology and Traversals",
  minutes: 60,
  learn: ["Use tree vocabulary: root, parent, child, leaf, height, depth", "Build a binary tree from nodes and from a level-order list", "Write preorder, inorder, postorder (DFS) and level-order (BFS) traversals", "Compute height, size and other properties recursively"],
  why: "Trees model hierarchies: folders, HTML pages, company charts, decisions, expressions. Tree questions (traversals, depth, paths) are among the most common in interviews, and they are the natural home of recursion.",
  realWorld: "A file system, the DOM of a web page, a family tree, a parser's expression tree, a database index.",
  simple: "A tree is a set of nodes connected so that there is one <strong>root</strong> at the top, and every other node has exactly one <strong>parent</strong>. A <strong>binary</strong> tree gives each node at most two children: <em>left</em> and <em>right</em>.",
  detail: `${table(["Term", "Meaning"], [["root", "the top node, no parent"], ["leaf", "a node with no children"], ["depth of a node", "edges from the root to it (root = 0)"], ["height of a tree", "longest root-to-leaf path (number of levels, or edges, depending on the book; here: number of nodes on the longest path)"], ["subtree", "a node together with all its descendants"], ["full / complete / balanced", "every node has 0 or 2 children / all levels full except maybe the last / heights of subtrees differ by at most 1"]])}
<h3>Traversals</h3>
${table(["Traversal", "Order", "Typical use"], [["preorder (DFS)", "node, left, right", "copy a tree, serialise"], ["inorder (DFS)", "left, node, right", "sorted order of a BST"], ["postorder (DFS)", "left, right, node", "delete a tree, evaluate expressions"], ["level order (BFS)", "level by level, using a queue", "shortest path, levels, width"]])}
<p>DFS traversals are three lines of recursion; the only difference is where you place the &quot;visit&quot; line. Their space is O(h) for the recursion stack (h = height; O(log n) when balanced, O(n) for a chain). Level order uses a queue: O(w) space (w = the widest level).</p>
<h3>Recursive thinking on trees</h3>
<p>Most properties follow one template: handle the empty tree (<code>None</code>) as the base case, solve the left and right subtrees, combine. Height is <code>1 + max(height(left), height(right))</code>; size is <code>1 + size(left) + size(right)</code>; a path sum asks the same question of each child with a smaller target.</p>
<h3>Input format used in this course</h3>
<p>Trees are given as a level-order list in which <code>null</code> marks a missing child: <code>3 9 20 null null 15 7</code> is the tree with root 3, children 9 and 20, and 20's children 15 and 7. The starter code includes a <code>build_tree</code> function for this.</p>`,
  syntax: { code: `def inorder(node):\n    if node is None:\n        return []\n    return inorder(node.left) + [node.val] + inorder(node.right)\n\ndef height(node):\n    return 0 if node is None else 1 + max(height(node.left), height(node.right))`, note: "Base case: None." },
  diagram: graph("A binary tree", "Root 3 with children 9 and 20; node 20 has children 15 and 7. Nodes 9, 15 and 7 are leaves.", 600, 250,
    [node("a", "3", 300, 36), node("b", "9", 170, 120), node("c", "20", 430, 120), node("d", "15", 350, 205), node("e", "7", 510, 205)],
    [{ from: "a", to: "b" }, { from: "a", to: "c" }, { from: "c", to: "d" }, { from: "c", to: "e" }]),
  example: { code: TREE_SETUP + `\ndef preorder(n):\n    return [] if n is None else [n.val] + preorder(n.left) + preorder(n.right)\ndef inorder(n):\n    return [] if n is None else inorder(n.left) + [n.val] + inorder(n.right)\ndef postorder(n):\n    return [] if n is None else postorder(n.left) + postorder(n.right) + [n.val]\ndef height(n):\n    return 0 if n is None else 1 + max(height(n.left), height(n.right))\ndef size(n):\n    return 0 if n is None else 1 + size(n.left) + size(n.right)\ndef level_order(root):\n    levels, queue = [], deque([root] if root else [])\n    while queue:\n        levels.append([n.val for n in queue])\n        for _ in range(len(queue)):\n            n = queue.popleft()\n            if n.left:\n                queue.append(n.left)\n            if n.right:\n                queue.append(n.right)\n    return levels\n\nroot = build_tree("3 9 20 null null 15 7".split())\nprint(preorder(root), inorder(root), postorder(root))\nprint(level_order(root), height(root), size(root))\nprint(height(None), level_order(None))`, out: `[3, 9, 20, 15, 7] [9, 3, 15, 20, 7] [9, 15, 7, 20, 3]\n[[3], [9, 20], [15, 7]] 3 5\n0 []` },
  lineByLine: [["build_tree(tokens)", "Reads the level-order list with a queue of nodes waiting for children."], ["preorder / inorder / postorder", "Identical code except for where the node's value is placed."], ["level_order", "<code>len(queue)</code> at the start of each round is the size of the current level."], ["height(None) = 0", "The base case that ends the recursion."]],
  dryRun: { intro: "Inorder of the tree <code>3 / (9, 20 / (15, 7))</code>:", headers: ["call", "does", "output so far"], rows: [["inorder(3)", "go left first", ""], ["inorder(9)", "left None, emit 9, right None", "9"], ["back at 3", "emit 3", "9 3"], ["inorder(20)", "left 15: emit 15", "9 3 15"], ["back at 20", "emit 20, then right 7", "9 3 15 20 7"]] },
  realExample: { intro: "Directory sizes are a postorder computation: a folder's size is known only after its children are measured.", code: `def total_size(folder):\n    return folder["size"] + sum(total_size(child) for child in folder.get("children", []))\ntree = {"size": 1, "children": [{"size": 10}, {"size": 5, "children": [{"size": 20}]}]}\nprint(total_size(tree))`, out: `36` },
  mistakes: ["Forgetting the <code>None</code> base case.", "Mixing up inorder, preorder and postorder.", "Confusing height measured in nodes versus edges (state which one you use).", "Hitting RecursionError on a chain-shaped tree with 100,000 nodes (use an explicit stack).", "Mutating shared lists in recursion instead of returning values."],
  practices: ["Write the base case first.", "Draw a small tree and trace the recursion.", "State height conventions."],
  interview: ["Traverse a binary tree in all four orders.", "Find the maximum depth.", "Check whether a tree is symmetric.", "Level order traversal; zig-zag order.", "Lowest common ancestor."],
  practiceQs: ["Give the postorder of a tree whose preorder is 1 2 3 and inorder is 2 1 3.", "How many leaves can a binary tree with n nodes have at most?", "What is the space complexity of recursive inorder?", "Why does level order use a queue?"],
  revision: ["Root, parent, child, leaf, height.", "Pre/in/post = DFS; level order = BFS with a queue.", "Template: base case None, solve both sides, combine.", "Recursion depth = height."],
  hinglish: "Tree mein ek root hota hai aur har node ke bachche hote hain; binary tree mein zyada se zyada do (left, right). Preorder mein node pehle, inorder mein beech mein aur postorder mein baad mein aata hai. Level order ke liye queue use hoti hai.",
  quiz: [
    mcq("Which traversal visits left, node, right?", ["Preorder", "Inorder", "Postorder", "Level order"], 1, "In-order: the node comes between its subtrees."),
    mcq("Which structure does level-order traversal use?", ["Stack", "Queue", "Set", "Heap"], 1, "A queue processes nodes in the order discovered."),
    mcq("What is the height (in nodes) of a single-node tree?", ["0", "1", "2", "Undefined"], 1, "One node on the longest path.", "OUTPUT_PREDICTION"),
    mcq("What is the base case of recursive tree functions?", ["The root", "A leaf only", "None (an empty tree)", "Depth 0"], 2, "It handles empty subtrees too."),
    mcq("What is the recursion depth for a tree of height h?", ["O(1)", "O(h)", "O(n²)", "O(log h)"], 1, "One frame per level.")
  ],
  tasks: [
    task("Tree traversals", "The input is a level-order list (null marks a missing child). Print the preorder, inorder and postorder traversals on three lines, values separated by spaces. The starter builds the tree for you.", TREE_SETUP + "\nroot = build_tree(input().split())\n# print preorder, inorder and postorder\n", TREE_SETUP + `\ndef pre(n):\n    return [] if n is None else [n.val] + pre(n.left) + pre(n.right)\ndef ino(n):\n    return [] if n is None else ino(n.left) + [n.val] + ino(n.right)\ndef post(n):\n    return [] if n is None else post(n.left) + post(n.right) + [n.val]\n\nroot = build_tree(input().split())\nfor order in (pre, ino, post):\n    print(" ".join(map(str, order(root))))`, [["3 9 20 null null 15 7", "3 9 20 15 7\n9 3 15 20 7\n9 15 7 20 3"], ["1 null 2 3", "1 2 3\n1 3 2\n3 2 1"]], [["3 9 20 null null 15 7", "3 9 20 15 7\n9 3 15 20 7\n9 15 7 20 3"], ["1 null 2 3", "1 2 3\n1 3 2\n3 2 1"], ["5", "5\n5\n5"], ["1 2 3 4 5 6 7", "1 2 4 5 3 6 7\n4 2 5 1 6 3 7\n4 5 2 6 7 3 1"], ["2 1", "2 1\n1 2\n1 2"]]),
    task("Depth and levels", "The input is a level-order list. Print the maximum depth (number of nodes on the longest root-to-leaf path) on the first line, then each level of the tree on its own line (values separated by spaces).", TREE_SETUP + "\nroot = build_tree(input().split())\n# print the depth, then the levels\n", TREE_SETUP + `\nroot = build_tree(input().split())\nlevels = []\nqueue = deque([root] if root else [])\nwhile queue:\n    levels.append([n.val for n in queue])\n    for _ in range(len(queue)):\n        n = queue.popleft()\n        if n.left:\n            queue.append(n.left)\n        if n.right:\n            queue.append(n.right)\nprint(len(levels))\nfor level in levels:\n    print(" ".join(map(str, level)))`, [["3 9 20 null null 15 7", "3\n3\n9 20\n15 7"], ["1", "1\n1"]], [["3 9 20 null null 15 7", "3\n3\n9 20\n15 7"], ["1", "1\n1"], ["1 2 null 3 null 4", "4\n1\n2\n3\n4"], ["1 2 3 4 5 6 7", "3\n1\n2 3\n4 5 6 7"], ["1 null 2", "2\n1\n2"]]),
  ],
});

